# Adds the December 2026 family readings (weeks 49–52) to family_data.js, keeping the existing days as they are.
# Verse text comes from the same KJV text Joined shows (texts/*.json; Isaiah from tools/kjv_build).
import json,re,sys
sys.path.insert(0,'tools')
src=open('family_data.js').read()
W=json.loads(re.search(r'const FAM_WEEKS=(\{.*?\});\n',src,re.S).group(1))
OUT=json.loads(re.search(r'const FAM=(\[.*\]);',src,re.S).group(1))
OUT=[d for d in OUT if d['d']<'2026-11-30']
IDS={'Micah':'mic','Nahum':'nahum','Habakkuk':'hab','Zephaniah':'zeph','Haggai':'hag','Zechariah':'zech','Malachi':'mal','Luke':'luke'}
TX={}
def chap(book,c):
    if book=='Isaiah':
        if 'Isaiah' not in TX:
            from kjv_build import book as kb,OS
            TX['Isaiah']=kb(OS.index('Isa'))
        return TX['Isaiah'][str(c)]
    if book not in TX:TX[book]=json.load(open(f'texts/{IDS[book]}.json'))['kjv']
    return TX[book][str(c)]
def V(spec):
    book,rest=spec[:spec.rfind(' ')],spec[spec.rfind(' ')+1:]
    out=[]
    for part in rest.split(';'):
        cc,vv=part.split(':');c=int(cc)
        for seg in vv.split(','):
            a,z=(seg.split('-')+[seg])[:2]
            for i in range(int(a),int(z)+1):out.append([c,i,chap(book,c)[i-1]])
    return out
lab=lambda s:s.replace('-','–').replace(',',', ').replace(';','; ')
CFM='https://www.churchofjesuschrist.org/study/manual/come-follow-me-for-home-and-church-old-testament-2026/'
